import{H as e,V as t,et as n,j as r}from"./chunks/framework.ByEJxCeM.js";import"./chunks/assets.Capd0F6S.js";var i=JSON.parse(`{"title":"事务四大特性","description":"","frontmatter":{},"headers":[],"relativePath":"java/transaction-management/acid-properties.md","filePath":"java/transaction-management/acid-properties.md"}`),a={name:`java/transaction-management/acid-properties.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="事务四大特性" tabindex="-1">事务四大特性 <a class="header-anchor" href="#事务四大特性" aria-label="Permalink to “事务四大特性”">​</a></h1><p>面试题：事务有哪些特性？</p><ul><li><p>原子性（Atomicity）：事务是不可分割的最小单元，要么全部成功，要么全部失败。</p></li><li><p>一致性（Consistency）：事务完成时，必须使所有的数据都保持一致状态。</p></li><li><p>隔离性（Isolation）：数据库系统提供的隔离机制，保证事务在不受外部并发操作影响的独立环境下运行。</p></li><li><p>持久性（Durability）：事务一旦提交或回滚，它对数据库中的数据的改变就是永久的。</p></li></ul><p>事务的四大特性简称为：ACID</p><p><img src="/blog-notes/assets/image-39.GQhDosmA.png" alt="imagepng" width="1497" height="456"></p><ul><li><p><strong>原子性（Atomicity）</strong> ：原子性是指事务包装的一组sql是一个不可分割的工作单元，事务中的操作要么全部成功，要么全部失败。</p></li><li><p><strong>一致性（Consistency）</strong>：一个事务完成之后数据都必须处于一致性状态。</p><ul><li><p>如果事务成功的完成，那么数据库的所有变化将生效。</p></li><li><p>如果事务执行出现错误，那么数据库的所有变化将会被回滚(撤销)，返回到原始状态。</p></li></ul></li><li><p><strong>隔离性（Isolation）</strong>：多个用户并发的访问数据库时，一个用户的事务不能被其他用户的事务干扰，多个并发的事务之间要相互隔离。</p><ul><li>一个事务的成功或者失败对于其他的事务是没有影响。</li></ul></li><li><p><strong>持久性（Durability）</strong>：一个事务一旦被提交或回滚，它对数据库的改变将是永久性的，哪怕数据库发生异常，重启之后数据亦然存在。</p></li></ul>`,6)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};